// =====================================================================
// WF4 - Preparar el registro del error
// El Error Trigger entrega datos distintos según dónde ocurrió el fallo:
//  - "execution": falló un nodo durante la ejecución.
//  - "trigger":   falló el disparador (por ejemplo el Schedule).
// Seguridad: no se guarda el "stack" técnico completo, solo lo necesario
// para diagnosticar; el mensaje se recorta a 2000 caracteres.
// =====================================================================
const d = $input.first().json;
const ejecucion = d.execution || {};
const disparador = d.trigger || {};
const error = ejecucion.error || disparador.error || {};

return [{
  json: {
    workflow: (d.workflow && d.workflow.name) || 'Desconocido',
    nodo: ejecucion.lastNodeExecuted || (error.node && error.node.name) || 'No identificado',
    mensaje: String(error.message || 'Error sin mensaje').slice(0, 2000),
    ejecucion_id: ejecucion.id ? String(ejecucion.id) : 'Sin ejecucion',
    url_ejecucion: ejecucion.url || 'Sin URL',
    detalle: {
      origen: d.trigger ? 'disparador' : 'ejecucion',
      modo: ejecucion.mode || disparador.mode || null,
      workflow_id: (d.workflow && d.workflow.id) || null,
      descripcion: error.description || null,
    },
  },
}];

parameters.query:
INSERT INTO errores (workflow, nodo, mensaje, ejecucion_id, url_ejecucion, detalle)
VALUES ($1, $2, $3, $4, $5, $6::jsonb)
RETURNING id, workflow, nodo;
